arguments.command:
mkdir -p notes && cat > notes/PRC-201.md <<'EOF'
# PRC-201 調査メモ
軌道: T2（金額の計算、3 ファイル、直近の commit で入った退行）。HEAD 8287509 (master)。
完了の条件: `bin/price 999` が 899 を返す（10% 引き、切り捨て）。
原因: 8287509 "tidy up rounding" が `$1*90/100`（切り捨て）を `($1*90+99)/100`（切り上げ）に変えた。
同じ型の箇所（検索 `99) / 100`、3 件）: bin/price, bin/quote, lib/invoice.sh。全て同じ式 → 全て戻す。
設計: 解は 1 つ（コメントの仕様「rounded down」に戻す）。他の直し方は仕様に反するため採らない。
戻せない操作: なし。未確認: quote/invoice の呼び出し元（リポジトリ内に無い）。
EOF
cat > tests/price_test.sh <<'EOF'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash -c 'source lib/invoice.sh' _ 2>/dev/null; bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
EOF
ls lib; bash scripts/verify.sh

